# maximum overlap of each demo's standout shape against remaining dots, across translations and dihedral orientations
def symmetries(cells):
    # local normalized shape; generate dihedral transforms on arbitrary coords
    out=[]
    for k in range(4):
        for flip in [False,True]:
            pts=[]
            for r,c in cells:
                if flip: c=-c
                for _ in range(k): r,c=c,-r
                pts.append((r,c))
            mr=min(r for r,c in pts); mc=min(c for r,c in pts)
            out.append(frozenset((r-mr,c-mc) for r,c in pts))
    return list(dict.fromkeys(out))
def best_overlap(shape, dots, h, w):
    res=[]
    for shape2 in symmetries(shape):
        sh=max(r for r,c in shape2)+1; sw=max(c for r,c in shape2)+1
        for r0 in range(h-sh+1):
            for c0 in range(w-sw+1):
                placed={(r0+r,c0+c) for r,c in shape2}
                ov=len(placed & set(dots))
                res.append((ov,r0,c0,shape2))
    return sorted(res,reverse=True,key=lambda x:x[0])[:10]
